import sys


def main():
    flags = []
    filename = None

    i = 1
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg == '-':
            filename = '-'
        elif arg.startswith('-'):
            for ch in arg[1:]:
                if ch in ('l', 'w', 'c'):
                    flags.append(ch)
                else:
                    print(f"unknown flag: {ch}", file=sys.stderr)
                    sys.exit(1)
        else:
            filename = arg
        i += 1

    if not flags:
        flags = ['l', 'w', 'c']

    # Determine order: always lines, words, characters
    counts = {}
    for f in flags:
        counts[f] = None

    if filename is None or filename == '-':
        data = sys.stdin.buffer.read()
    else:
        with open(filename, 'rb') as f:
            data = f.read()

    byte_count = len(data)
    word_count = len(data.split())

    # Lines: count newline characters, but a final line with no trailing
    # newline still counts as a line (if there's any content).
    newline_count = data.count(b'\n')
    if data and not data.endswith(b'\n'):
        newline_count += 1

    counts['l'] = newline_count
    counts['w'] = word_count
    counts['c'] = byte_count

    result = []
    for f in ['l', 'w', 'c']:
        if f in counts:
            result.append(str(counts[f]))
    print(' '.join(result))


if __name__ == '__main__':
    main()

